<script setup lang="ts">
import {onBeforeUnmount,ref,watch} from 'vue'
import {api} from '../api'
import {useAppStore} from '../store'
import {traceLabel,tracePage,traceState,type TraceEvent} from '../run-trace'
const props=defineProps<{runId:string;sessionId:string;runState?:string}>(),store=useAppStore()
const expanded=ref(false),loading=ref(false),error=ref(''),events=ref<TraceEvent[]>([]),snapshot=ref<any>(null),gap=ref(false),legacy=ref(false)
let epoch=0,cursor=0,request:AbortController|undefined,timer:ReturnType<typeof setTimeout>|undefined
function reset(){++epoch;request?.abort();clearTimeout(timer);cursor=0;events.value=[];snapshot.value=null;gap.value=false;legacy.value=false;error.value='';loading.value=false}
async function load(){
  if(loading.value||!expanded.value)return
  const stamp=epoch;loading.value=true;error.value='';request=new AbortController()
  try{const page=await api.runTrace(props.runId,cursor,request.signal);if(stamp!==epoch)return
    const rows=tracePage(page,props.runId,props.sessionId,store.user?.id||'',store.organizationId,cursor)
    events.value.push(...rows);cursor=page.next_cursor;snapshot.value=page;gap.value||=page.history_gap;legacy.value||=page.legacy_timestamps
    if(events.value.length>2048){events.value=events.value.slice(-2048);gap.value=true}
  }catch(e:any){if(stamp===epoch&&e.name!=='AbortError'){error.value=e.message;if([401,403,404].includes(e.status)||e.code==='AUTH_CHANGED'){events.value=[];snapshot.value=null;cursor=0;gap.value=false;legacy.value=false}}}
  finally{if(stamp===epoch){loading.value=false;clearTimeout(timer);if(expanded.value&&!error.value&&!gap.value&&['queued','running','cancelling'].includes(snapshot.value?.state))timer=setTimeout(()=>void load(),2000)}}
}
function toggle(event:Event){expanded.value=(event.target as HTMLDetailsElement).open;if(expanded.value)void load();else{clearTimeout(timer);request?.abort()}}
function refresh(){reset();void load()}
function time(value:string|null){if(!value)return '时间未记录';const date=new Date(value);return Number.isNaN(date.getTime())?'时间未记录':date.toLocaleTimeString('zh-CN',{hour12:false})}
watch(()=>[props.runId,props.sessionId,store.user?.id,store.user?.role,store.organizationId],()=>{reset();if(expanded.value)void load()})
watch(()=>props.runState,()=>{if(expanded.value&&!loading.value)void load()})
onBeforeUnmount(reset)
</script>
<template><details class="run-trace" @toggle="toggle"><summary>执行记录与检索上下文 <span>{{traceState(snapshot?.state||runState||'')}}</span></summary><div class="trace-body" tabindex="0" aria-label="执行记录内容"><header><small>本轮 {{runId.slice(0,8)}}</small><button @click="refresh" :disabled="loading">重新核查</button></header><p v-if="error" role="alert">{{error}}</p><p v-if="gap" class="notice">部分历史记录缺失，不能据此判断完整执行过程。</p><p v-if="legacy" class="notice">旧事件未保存时间戳，仅按原始序号排列。</p><p v-if="snapshot?.remaining_seconds!=null">剩余执行预算：{{Math.max(0,snapshot.remaining_seconds).toFixed(1)}} 秒</p><ol aria-label="本轮执行时间线"><li v-for="item in events" :key="item.sequence" :data-event="item.event"><time>{{time(item.recorded_at)}}</time><div><strong>{{traceLabel(item)}}</strong><small v-if="item.name||item.agent">{{item.name||item.agent}}</small><span v-if="item.tool_names?.length">{{item.tool_names.join('、')}}</span><span v-if="item.file_count!=null">{{item.file_count}} 份文件</span><span v-if="item.elapsed_ms!=null">{{item.elapsed_ms.toFixed(0)}} ms</span><code v-if="item.code||item.error_code">{{item.code||item.error_code}}</code></div></li></ol><p v-if="loading" role="status">正在读取执行记录…</p><button v-if="snapshot?.has_more&&!gap" :disabled="loading" @click="load">读取后续记录</button><section v-if="snapshot" class="knowledge-context" aria-label="本轮检索上下文"><h4>RAG 检索上下文</h4><p>检索命中、被回答引用的证据与仅用于理解的父块分别标注。工具回执不属于知识库证据。</p><p v-if="snapshot.knowledge.status==='revoked'" class="notice">资料授权或发布范围已变化，当前无法查看原检索内容。</p><p v-else-if="snapshot.knowledge.status==='unavailable'">此运行未保存可展示的检索上下文。</p><template v-else><p v-if="snapshot.knowledge.budget_tokens!=null">证据预算 {{snapshot.knowledge.used_tokens}} / {{snapshot.knowledge.budget_tokens}} tokens · 父块 {{snapshot.knowledge.parent_context_tokens}} tokens</p><p v-if="!snapshot.knowledge.sources.length">本轮没有知识库证据。</p><article v-for="source in snapshot.knowledge.sources" :key="source.number"><header><strong>[{{source.number}}] {{source.source_name}}</strong><span>{{({cited:'已引用',retrieved:'已检索 · 未引用',excluded:'已排除'} as Record<string,string>)[source.status]}}</span></header><small>叶子 {{source.chunk_id}}<template v-if="source.page_number"> · 第 {{source.page_number}} 页</template></small><blockquote>{{source.excerpt}}</blockquote></article><article v-for="parent in snapshot.knowledge.parents" :key="parent.context_id" class="parent"><header><strong>{{parent.title}}</strong><span>父块 · 仅供理解</span></header><small>关联证据 {{parent.for_numbers.map((n:number)=>`[${n}]`).join('、')}} · 不单独作为引用</small><blockquote>{{parent.excerpt}}</blockquote><small v-if="parent.truncated">仅显示部分父块内容。</small></article><p v-if="snapshot.knowledge.truncated" class="notice">上下文展示已截断。</p></template><p v-for="(call,index) in snapshot.model_context" :key="index">模型上下文：{{call.input_tokens}} / {{call.input_budget_tokens}} tokens（{{call.measurement==='reported'?'供应商报告':'估算'}}）</p></section></div></details></template>
<style scoped>
.run-trace{margin-top:18px;border:1px solid var(--line);border-radius:8px;background:var(--surface);font-size:12px}.run-trace summary{padding:14px;cursor:pointer;color:var(--green);font-weight:600}.run-trace summary span{float:right;color:var(--muted);font-weight:400}.trace-body{padding:0 16px 16px;max-height:min(640px,40dvh);overflow:auto}.trace-body header{display:flex;gap:12px;justify-content:space-between;align-items:center}.trace-body button{border:1px solid var(--line);border-radius:5px;background:transparent;color:var(--green);padding:6px 10px;font-size:11px}.trace-body ol{list-style:none;padding:0;margin:18px 0}.trace-body li{display:grid;grid-template-columns:85px 1fr;gap:10px;border-left:2px solid var(--line);padding:0 0 18px 12px}.trace-body time,small{color:var(--muted);font-size:10px}.trace-body li div{display:flex;flex-wrap:wrap;gap:6px 12px}.trace-body li strong{font-weight:500}.trace-body li[data-event=tool_failed],.notice{color:#9b563b}.knowledge-context{border-top:1px solid var(--line);padding-top:16px}.knowledge-context h4{margin:0 0 12px;font:17px 'Noto Serif SC',serif}.knowledge-context p{line-height:1.8;color:var(--muted)}.knowledge-context article{margin:12px 0;padding:12px;border:1px solid var(--line);border-radius:6px;overflow-wrap:anywhere}.knowledge-context blockquote{white-space:pre-wrap;margin:12px 0 0;line-height:1.8;color:var(--ink)}.knowledge-context header span{font-size:10px;color:var(--green);flex-shrink:0}.parent{border-style:dashed!important}@media(max-width:520px){.trace-body{padding-inline:12px}.trace-body li{grid-template-columns:1fr;gap:4px}.run-trace summary span{float:none;margin-left:12px}}
</style>
